-- v69: 33 materi kegiatan outdoor (m8-m40) untuk halaman Materi.
-- MENGGANTIKAN materi-outdoor-v68.sql -- file ini sudah memuat semuanya.
-- Jalankan di Supabase -> SQL Editor. Aman diulang (upsert per id).
-- Kolom "tautan" menampilkan tombol "Buka referensi" di halaman detail materi.

insert into materi (id, judul, rumpun, tingkat, acuan, tautan, isi) values
  ('m8', 'Packing Seimbang: Aturan 20 Persen', 'Logistik', 'Dasar', 'Kompilasi catatan lapangan anggota', null,
   'Berat carrier idealnya tidak lebih dari 20 persen berat badan untuk pendakian satu-dua hari. Barang paling berat diletakkan menempel punggung dan setinggi bahu, bukan di dasar tas. Jas hujan, P3K, headlamp, dan sarung tangan selalu di kantong luar — barang darurat tidak boleh dikubur.'),
  ('m9', 'Komunikasi Darurat Tanpa Sinyal', 'Keselamatan', 'Dasar', 'Standar komunikasi lapangan RCS.CBS', null,
   'Sepakati kode sebelum berangkat: satu tiupan peluit panjang berarti berhenti dan berkumpul, tiga tiupan pendek beruntun berarti minta tolong. Tentukan titik kumpul ulang setiap kali melewati persimpangan jalur, dan titipkan rencana rute tertulis kepada anggota yang berjalan paling belakang.'),
  ('m10', 'Memilih Tempat Kemah yang Aman', 'Keterampilan', 'Dasar', 'Leave No Trace Center for Outdoor Ethics', 'https://lnt.org/why/7-principles',
   'Hindari tiga tempat: di bawah pohon besar yang lapuk, di cekungan bekas aliran air meski tampak kering, dan di punggungan terbuka saat musim badai. Pilih tanah datar dengan drainase alami, dan usahakan tiba saat langit masih terang agar sempat membaca sekeliling.'),
  ('m11', 'Tiga Simpul Wajib di Lapangan', 'Keterampilan', 'Menengah', 'Modul Pendidikan Dasar RCS.CBS', null,
   'Figure eight untuk ujung tambat, bowline untuk simpul tetap yang mudah dilepas, dan taut-line untuk menegangkan tali flysheet. Latih ketiganya sampai bisa dipasang dengan mata tertutup — di lapangan kamu akan memakainya dalam gelap dengan tangan dingin.'),
  ('m12', 'Panjat Tebing: Cek Pasangan Sebelum Bergerak', 'Keterampilan', 'Menengah', 'UIAA — Federasi Panjat Tebing Internasional', 'https://www.theuiaa.org/safety/',
   'Sebelum pemanjat bergerak, lakukan cek pasangan: simpul terikat benar, harness terpasang rapat, dan belayer siap dengan perangkat terkunci. UIAA menekankan bahwa hampir semua kecelakaan panjat bermula dari komunikasi yang terlewat, bukan dari kegagalan alat. Helm dipakai sejak berdiri di bawah tebing, bukan hanya saat memanjat.'),
  ('m13', 'Susur Goa: Aturan Tiga Sumber Cahaya', 'Keterampilan', 'Menengah', 'National Speleological Society (NSS), AS', 'https://caves.org/education',
   'Komunitas penelusur goa dunia mewajibkan tiga hal: setiap orang membawa tiga sumber cahaya yang terpisah, tidak pernah masuk goa sendirian (minimal tiga orang), dan selalu menitipkan rencana perjalanan kepada orang di luar. Goa tidak menoleransi cuaca — hujan di hulu bisa menaikkan air dalam hitungan menit, padahal di dalam goa langit tidak terlihat.'),
  ('m14', 'Susur Sungai: Baca Arus Sebelum Masuk Air', 'Keselamatan', 'Menengah', 'American Canyoneering Association (ACA)', 'https://canyoneering.net/',
   'Susur sungai ala canyoning internasional menekankan urutan yang tetap: amati arus dari tepi, tentukan titik keluar darurat setiap puluhan meter, dan jangan pernah mengikat diri ke tali saat berada di dalam arus. Bila tersapu, posisi telentang dengan kaki mengarah ke hilir untuk menahan benturan batu.'),
  ('m15', 'Jeram: Pelampung, Helm, dan Renang Bertahan', 'Keselamatan', 'Menengah', 'American Whitewater — Safety Code', 'https://www.americanwhitewater.org/explore/safety/safety-code',
   'Kode keselamatan arus deras American Whitewater sederhana: pelampung (PFD) dan helm wajib sejak kelas jeram paling mudah; jangan berdiri di arus yang lebih dalam dari lutut karena kaki bisa terjepit batu; dan regu menyepakati sinyal tangan sebelum berangkat. Menolong korban dimulai dengan melempar tali, bukan ikut terjun.'),
  ('m16', 'Menyeberangi Sungai: Keputusan Ada di Tepi', 'Keselamatan', 'Dasar', 'New Zealand Mountain Safety Council (NZMSC)', 'https://www.mountainsafety.org.nz/learn/skills/river-safety',
   'Dewan keselamatan gunung Selandia Baru merumuskan satu kalimat penyelamat: if in doubt, do not cross — ragu sedikit saja, jangan menyeberang. Tanda sungai tak aman: air di atas lutut yang keruh, bunyi batu berguling di dasar, atau arus yang menghanyutkan ranting besar. Bila tetap menyeberang, lepas pengikat pinggang carrier agar tas mudah diloloskan saat jatuh.'),
  ('m17', 'Petir di Lapangan: Aturan 30/30', 'Cuaca', 'Dasar', 'NOAA / National Weather Service, AS', 'https://www.weather.gov/safety/lightning',
   'When thunder roars, go indoors — bunyi guruh berarti petir sudah cukup dekat untuk membunuh. Aturan 30/30: bila jeda antara kilat dan guruh kurang dari 30 detik, segera turun dari punggungan dan jangan berteduh di bawah pohon tunggal; tunggu 30 menit setelah guruh terakhir sebelum kembali bergerak.'),
  ('m18', 'Snorkeling & Menyelam: Aturan Emas di Bawah Air', 'Keselamatan', 'Menengah', 'Divers Alert Network (DAN)', 'https://dan.org/health-medicine/health-resources/health-safety-guidelines/',
   'DAN, lembaga keselamatan selam dunia, menetapkan aturan yang tidak bisa ditawar: selalu menyelam berpasangan (buddy), periksa alat bersama sebelum turun, dan jangan pernah menahan napas saat naik ke permukaan — paru-paru bisa mengembang dan pecah. Naiklah perlahan, dan jangan menyelam dalam 24 jam sebelum naik gunung atau terbang.'),
  ('m19', 'Di Pantai: Kenali Rip Current, Arus Balik Pembunuh', 'Keselamatan', 'Dasar', 'RNLI — Royal National Lifeboat Institution', 'https://rnli.org/water-safety/know-the-risks/rip-currents',
   'Rip current adalah penyebab utama kecelakaan di pantai berombak: arus sempit yang menarik lurus ke tengah laut. Cirinya kanal air lebih tenang dan lebih gelap di antara barisan ombak. Bila terseret, JANGAN melawan arus ke tepi — mengambanglah, angkat tangan minta tolong, lalu berenang menyamping sejajar pantai sampai lepas dari arus.'),
  ('m20', 'Bertemu Hewan Liar: Jarak Adalah Keselamatan', 'Keselamatan', 'Dasar', 'U.S. National Park Service', 'https://www.nps.gov/subjects/watchingwildlife/7ways.htm',
   'Aturan taman nasional Amerika: jaga jarak minimal 23 meter dari hewan liar dan 91 meter dari hewan besar — bila hewan mengubah perilakunya karenamu, kamu sudah terlalu dekat. Jangan pernah memberi makan, jangan mendekat demi foto, dan jangan berlari: mundur perlahan sambil tetap menghadap hewan.'),
  ('m21', 'Digigit Ular: Pertolongan Pertama yang Benar', 'Keselamatan', 'Dasar', 'Mayo Clinic — Snakebite First Aid', 'https://www.mayoclinic.org/first-aid/first-aid-snake-bites/basics/art-20056681',
   'Yang benar menurut panduan medis: jauhi ular, duduk tenang agar bisa tidak cepat menyebar, lepaskan cincin dan jam sebelum bengkak, bersihkan luka dan tutup kain bersih, lalu segera cari bantuan medis. Yang dilarang: mengisap bisa, menyayat luka, torniket, es, kafein, atau alkohol.'),
  ('m22', 'Di Habitat Buaya: Aturan Tepi Air', 'Keselamatan', 'Dasar', 'Be Crocwise — Pemerintah Northern Territory, Australia', 'https://becrocwise.nt.gov.au/',
   'Berlaku untuk muara dan sungai berlumpur di Sulawesi: pasang kemah jauh dari tepi air, jangan berdiri di tepi saat memancing atau mengambil air, dan jangan pernah membuang sisa makanan ke sungai. Buaya menghafal pola — jangan pakai titik air yang sama setiap hari, dan jangan berenang di perairan habitat buaya.'),
  ('m23', 'Monyet & Babi Hutan di Kemah: Amankan Makanan', 'Logistik', 'Dasar', 'U.S. National Park Service — Bear Safety: Storing Food', 'https://www.nps.gov/articles/bearsafetyfood.htm',
   'Prinsip dari wilayah beruang yang berlaku juga untuk monyet dan babi hutan: makanan, sampah, dan barang beraroma tidak pernah disimpan di dalam tenda. Simpan dalam wadah tertutup atau gantung jauh dari area tidur, cuci peralatan makan segera, dan jangan membakar sisa makanan di api unggun. Hewan yang pernah mendapat makanan dari manusia akan kembali — dan makin berani.'),
  ('m24', 'Bila Hewan Besar Menyerang: Tenang, Besar, Mundur', 'Keselamatan', 'Menengah', 'U.S. National Park Service — Wildlife Health & Safety', 'https://www.nps.gov/subjects/healthandsafety/wildlife.htm',
   'Saat berhadapan dengan hewan besar: tetap tenang, jangan berlari karena memicu naluri mengejar. Tegakkan badan dan buka jaket agar tampak besar, berbicara dengan suara rendah yang tenang, lalu mundur perlahan tanpa membelakangi. Bila hewan benar-benar menyerang secara ofensif, lawan sekuat tenaga — pura-pura mati hanya untuk serangan defensif seperti induk yang melindungi anak.'),
  ('m25', 'Pendarahan Hebat: Tekan, Kemas, Jangan Dilepas', 'Keselamatan', 'Dasar', 'Stop the Bleed — American College of Surgeons', 'https://www.stopthebleed.org/',
   'Kampanye Stop the Bleed mengajarkan tiga langkah: tekan luka dengan kain atau tangan, padatkan luka yang dalam dengan kain, lalu balut kuat dan jangan dibuka-buka untuk diperiksa. Torniket hanya untuk pendarahan mengucur di lengan atau kaki, dipasang 5-7 cm di atas luka, dan catat jam pemasangannya. Pendarahan hebat bisa merenggut nyawa dalam lima menit — lebih cepat daripada bantuan tiba.'),
  ('m26', 'CPR di Lapangan: Tekan 100-120 per Menit', 'Keselamatan', 'Menengah', 'American Red Cross', 'https://www.redcross.org/take-a-class/cpr',
   'Henti jantung dimenangkan oleh tangan yang berani menekan: telapak di tengah dada, dalam 5-6 cm, tempo 100-120 tekanan per menit. Red Cross menekankan: minta orang lain memanggil bantuan dulu, lalu menekan tanpa henti sampai bantuan tiba atau korban berespons. Jangan takut mematahkan tulang rusuk — yang lebih berbahaya adalah otak yang kehabisan oksigen.'),
  ('m27', 'Tandu Darurat: Kapan Boleh Memindahkan Korban', 'Keselamatan', 'Menengah', 'Materi Wilderness First Aid', null,
   'Aturan pertama: jangan pindahkan korban dengan dugaan cedera leher atau tulang belakang, kecuali lokasinya membahayakan nyawanya. Bila harus memindahkan, tandu darurat bisa dibuat dari dua jaket yang lengannya dilipat ke dalam lalu ditusuk dua batang kuat. Evakuasi tandu butuh minimal enam pengangkat bergantian — hitung tenaga regu sebelum memutuskan, agar regu tidak ikut menjadi korban.'),
  ('m28', 'Tersesat: Ingat STOP Sebelum Melangkah Lagi', 'Navigasi', 'Dasar', 'U.S. Forest Service', 'https://www.fs.usda.gov/visit/know-before-you-go/if-you-get-lost',
   'US Forest Service mengajarkan satu kata saat sadar tersesat: STOP. Stop — berhenti, jangan berjalan panik. Think — ingat titik terakhir posisimu pasti. Observe — amati tanda jalur, suara air, arah matahari. Plan — sering kali jawabannya adalah tetap di tempat dan membuat dirimu mudah terlihat. Orang yang berjalan panik memperluas area pencarian berkali lipat.'),
  ('m29', 'Sinyal Darurat: Tiga Kali Apa Saja', 'Keselamatan', 'Dasar', 'Standar SAR internasional', null,
   'Tiga kali apa saja dipahami di seluruh dunia sebagai panggilan minta tolong: tiga tiupan peluit, tiga titik api, tiga kilatan cahaya, dengan jeda di antaranya. Siang hari, cermin sinyal bisa terlihat puluhan kilometer; malam hari, kedipkan headlamp tiga-tiga. Untuk tim SAR udara, bentuk huruf besar di tanah terbuka: V berarti butuh bantuan, X berarti butuh bantuan medis.'),
  ('m30', 'PLB: Pemanggil Bantuan dari Langit', 'Keselamatan', 'Menengah', 'NOAA SARSAT / Cospas-Sarsat', 'https://www.sarsat.noaa.gov/cospas-sarsat-system-overview/',
   'Personal Locator Beacon (PLB) dan komunikator satelit memanggil SAR tanpa butuh sinyal HP: sekali diaktifkan, sinyal 406 MHz-nya ditangkap satelit Cospas-Sarsat dan diteruskan ke pos penyelamat lengkap dengan posisimu. Untuk kegiatan di luar jangkauan sinyal seperti gunung dan goa Sulawesi, inilah tombol darurat yang benar-benar selalu tersambung.'),
  ('m31', 'Diserang Kawanan Tawon: Lari, Tutupi Wajah', 'Keselamatan', 'Dasar', 'Panduan extension universitas AS (USDA)', null,
   'Bila sarang tawon tak sengaja terganggu, jangan memukul atau menyemprot — larilah menjauh secepatnya sambil melindungi wajah, masuk ke vegetasi rapat atau bangunan, dan jangan melompat ke air karena tawon menunggu di permukaan. Setelah aman, cabut penyengat yang tertinggal dengan menggesek kuku atau kartu, bukan mencubit. Bila korban disengat banyak kali atau mulai sulit bernapas, itu keadaan darurat medis.'),
  ('m32', 'Digigit Anjing Liar: Cuci 15 Menit, Waspada Rabies', 'Keselamatan', 'Dasar', 'World Health Organization (WHO)', 'https://www.who.int/news-room/fact-sheets/detail/rabies',
   'WHO menegaskan: luka gigitan atau jilatan anjing liar pada kulit terbuka wajib dicuci dengan sabun dan air mengalir selama 15 menit — langkah sederhana ini mematikan sebagian besar virus rabies di luka. Setelah itu segera ke fasilitas kesehatan untuk penilaian vaksin. Rabies hampir selalu fatal setelah gejala muncul, tetapi hampir selalu bisa dicegah bila ditangani segera.'),
  ('m33', 'Pacet & Lintah di Hutan Hujan', 'Keselamatan', 'Dasar', 'NSW National Parks, Australia', 'https://www.nationalparks.nsw.gov.au/get-inspired/stories/leeches-ticks-snakes-and-spiders',
   'Pacet aktif setelah hujan di hutan hujan tropis. Panduan taman nasional Australia: jangan ditarik paksa karena moncongnya bisa tertinggal di kulit — tunggu sampai kenyang dan lepas sendiri, atau usap dari samping dengan kuku. Bekas gigitannya gatal dan bisa berdarah lama; bersihkan dan tutup. Pencegahan paling efektif: celana panjang dimasukkan ke kaus kaki dan repellent di pergelangan.'),
  ('m34', 'Heat Stroke: Ketika Panas Tropis Mematikan', 'Cuaca', 'Dasar', 'NOAA / National Weather Service, AS', 'https://www.weather.gov/safety/heat-illness',
   'Bedakan heat exhaustion (keringat deras, lemas, pusing) dari heat stroke (kulit panas-kering, linglung, bisa pingsan) — yang kedua darurat medis yang membunuh dalam hitungan menit. Dinginkan korban secepatnya: pindahkan ke tempat teduh, basahi tubuh, kipasi, dan beri minum hanya bila sadar penuh. Di lapangan tropis, jadwalkan bagian berat sebelum pukul sepuluh pagi.'),
  ('m35', 'Gempa Saat di Pantai: Tsunami Bisa Menyusul', 'Keselamatan', 'Dasar', 'Ready.gov / FEMA, AS', 'https://www.ready.gov/tsunamis',
   'Bila kamu di pantai dan merasakan gempa kuat atau melihat laut tiba-tiba surut jauh, itulah peringatan alami tsunami: jangan menunggu sirine — segera lari ke tempat tinggi atau jauh ke daratan. Gelombang pertama sering bukan yang terbesar, jadi jangan kembali sebelum pihak berwenang menyatakan aman. Panduan ini berlaku penuh untuk pesisir Sulawesi.'),
  ('m36', 'Api Unggun Lepas Kendali: Kebakaran Hutan', 'Etika', 'Dasar', 'Ready.gov / FEMA, AS', 'https://www.ready.gov/wildfires',
   'Sebagian besar kebakaran hutan bermula dari api unggun manusia: padamkan dengan menyiram dan mengaduk bara sampai dingin disentuh, bukan cuma menimbun tanah. Bila melihat kebakaran saat berkegiatan, jauhi ke arah datangnya angin dan turun ke lembah — api bergerak paling cepat ke arah atas lereng. Laporkan segera; jangan mencoba memadamkan kebakaran yang sudah membesar.'),
  ('m37', 'Air Sungai Jangan Langsung Diminum', 'Logistik', 'Dasar', 'CDC, AS', 'https://www.cdc.gov/drinking-water/prevention/water-treatment-hiking-camping-traveling.html',
   'Air jernih yang mengalir pun bisa membawa parasit Giardia: CDC mewajibkan semua air alam diolah sebelum diminum. Urutan pilihan: rebus mendidih satu menit (tiga menit di ketinggian), atau saring dengan filter satu mikron lalu lanjutkan disinfeksi tablet atau UV untuk virus. Filter saja tidak membunuh virus — itu kesalahan paling umum di lapangan.'),
  ('m38', 'Sanitasi Kemah: Cuci Tangan Menyelamatkan Regu', 'Logistik', 'Dasar', 'CDC — Clean Hands', 'https://www.cdc.gov/clean-hands/about/index.html',
   'Wabah diare adalah penghancur kegiatan regu yang paling sering, dan CDC menempatkan cuci tangan pakai sabun sebagai pencegah nomor satu: sebelum menyiapkan makanan dan setelah buang air. Di kemah, buat titik cuci tangan sederhana dari jeriken gantung. Hand sanitizer boleh sebagai cadangan, tetapi sabun dan air tetap yang utama.'),
  ('m39', 'Sepuluh Barang Wajib (Ten Essentials)', 'Logistik', 'Dasar', 'REI Co-op, AS', 'https://www.rei.com/learn/expert-advice/ten-essentials.html',
   'Daftar Ten Essentials dari REI dipakai pendaki di seluruh dunia: navigasi, senter cadangan, tabir surya, P3K, pisau dan peralatan, pembuat api, tenda darurat, makanan lebih, air lebih, dan pakaian lebih. Kata kuncinya adalah lebih — bekal ekstra inilah yang membuat kejadian biasa tidak berubah menjadi keadaan darurat.'),
  ('m40', 'Tiga T Sebelum Berangkat: Rencana, Latihan, Bekal', 'Aturan', 'Dasar', 'AdventureSmart, Kanada', 'https://www.adventuresmart.ca/',
   'AdventureSmart Kanada merangkum persiapan pemula menjadi Tiga T: Trip planning — rencanakan rute dan titipkan ke orang terpercaya; Training — latih kemampuan sesuai medannya; Taking the essentials — bawa sepuluh barang wajib. Kegiatan yang aman dimenangkan sebelum berangkat, bukan di tengah jalur.')
on conflict (id) do update set
  judul = excluded.judul,
  rumpun = excluded.rumpun,
  tingkat = excluded.tingkat,
  acuan = excluded.acuan,
  tautan = excluded.tautan,
  isi = excluded.isi;
